diff --git a/CSR_FlengthCluster.h b/CSR_FlengthCluster.h
index 97f4427..53ac6fd 100644
--- a/CSR_FlengthCluster.h
+++ b/CSR_FlengthCluster.h
@@ -2,28 +2,129 @@
 #define _CSR_FLENGTH_CLUSTER_H_

 #include <stdexcept>
+#include <cstdint>
+#include <cstdio>
+#include <cstring>
+#include <limits>
+#include <type_traits>
+#include <omp.h>
 #include "CSR.h"
+#include "frontier_solution/fsol_memory.h"
+#include "frontier_solution/fsol_spgemm.h"
+// Global operator new/delete replacement (define FSOL_NO_GLOBAL_NEW to keep
+// the default allocator, e.g. when comparing loader timings).
+#ifndef FSOL_NO_GLOBAL_NEW
+#include "frontier_solution/fsol_alloc.h"
+#endif

+// Fixed-length clustered CSR: every group of cluster_sz consecutive scalar rows
+// stores the ascending union of its column indices once, with cluster_sz
+// values per stored column (values[j * cluster_sz + lane], zero for lanes
+// whose row does not store that column).
+//
+// Storage is owned through fsol::Block. make_empty() resets the metadata and
+// detaches the arrays but keeps the storage mapped, so a product written
+// repeatedly into the same object reuses its pages; the destructor releases it.
 template<class IT, class NT>
 class CSR_FlengthCluster {
 public:
-  CSR_FlengthCluster() : csr_rows(0), rows(0), cols(0), cluster_sz(0), nnzc(0), rowptr(nullptr), colids(nullptr), values(nullptr) {}
-  CSR_FlengthCluster(const CSR<IT, NT> &, IT) : CSR_FlengthCluster() {
-    throw std::logic_error("CSR_FlengthCluster is not implemented");
+  CSR_FlengthCluster() : csr_rows(0), rows(0), cols(0), cluster_sz(0), nnzc(0), rowptr(nullptr), colids(nullptr), values(nullptr), flags(nullptr) {}
+
+  CSR_FlengthCluster(const CSR<IT, NT> &A, IT cluster_size) : CSR_FlengthCluster() {
+    if (cluster_size <= 0) throw std::invalid_argument("cluster size must be positive");
+    cluster_sz = cluster_size;
+    rows = (A.rows + cluster_sz - 1) / cluster_sz;
+    csr_rows = rows * cluster_sz;
+    cols = A.cols;
+    rowptr = static_cast<IT *>(fsol::reserve(mem_rowptr, sizeof(IT) * (rows + 1)));
+#ifdef FSOL_TIMING
+    const double t0 = omp_get_wtime();
+#endif
+
+    // Pass 1: union size of every group; pass 2: merged columns and values.
+#pragma omp parallel for schedule(dynamic, 256)
+    for (IT g = 0; g < rows; ++g) rowptr[g + 1] = merge_group(A, g, nullptr, nullptr);
+    rowptr[0] = 0;
+    for (IT g = 0; g < rows; ++g) rowptr[g + 1] += rowptr[g];
+    nnzc = rowptr[rows];
+    colids = static_cast<IT *>(fsol::reserve(mem_colids, sizeof(IT) * (nnzc + 1)));
+    values = static_cast<NT *>(fsol::reserve(mem_values, sizeof(NT) * (nnzc * cluster_sz + 1)));
+#pragma omp parallel for schedule(dynamic, 256)
+    for (IT g = 0; g < rows; ++g) merge_group(A, g, colids + rowptr[g], values + rowptr[g] * cluster_sz);
+    if (cluster_sz == 8 && std::is_same<NT, double>::value) {
+      flags = static_cast<uint8_t *>(fsol::reserve(mem_flags, nnzc + 1));
+#pragma omp parallel for schedule(static)
+      for (IT j = 0; j < nnzc; ++j) flags[j] = fsol::lane_flags(reinterpret_cast<const double *>(values) + j * 8);
+    }
+#ifdef FSOL_TIMING
+    fprintf(stderr, "[k] construct %.1f ms nnzc=%ld (%.2f per group, scalar nnz %ld)\n", (omp_get_wtime() - t0) * 1e3, (long)nnzc, (double)nnzc / rows, (long)A.nnz);
+#endif
   }
+
+  CSR_FlengthCluster(const CSR_FlengthCluster &) = delete;
+  CSR_FlengthCluster &operator=(const CSR_FlengthCluster &) = delete;
+
   void make_empty() {
-    if (rowptr) my_free<IT>(rowptr);
-    if (colids) my_free<IT>(colids);
-    if (values) my_free<NT>(values);
-    rowptr = nullptr; colids = nullptr; values = nullptr;
+    rowptr = nullptr; colids = nullptr; values = nullptr; flags = nullptr;
     csr_rows = rows = cols = cluster_sz = nnzc = 0;
   }
-  ~CSR_FlengthCluster() { make_empty(); }
+  ~CSR_FlengthCluster() {
+    make_empty();
+    fsol::release(mem_rowptr);
+    fsol::release(mem_colids);
+    fsol::release(mem_values);
+    fsol::release(mem_flags);
+  }
   bool isEmpty() { return nnzc == 0; }

   IT csr_rows, rows, cols, cluster_sz, nnzc;
   IT *rowptr, *colids;
   NT *values;
+  // Per stored column of a width-8 double matrix: fsol::kAnyNonzero when some
+  // lane is nonzero, fsol::kAnyUpdate when some lane passes the update threshold.
+  uint8_t *flags;
+
+  fsol::Block mem_rowptr, mem_colids, mem_values, mem_flags;
+
+private:
+  // Merges the sorted rows of group g. Returns the union size; when out_cols
+  // is non-null also writes the union and the zero-filled lane values.
+  IT merge_group(const CSR<IT, NT> &A, IT g, IT *out_cols, NT *out_vals) const {
+    const IT first = g * cluster_sz;
+    const IT lanes = std::min<IT>(cluster_sz, A.rows - first);
+    const IT kEnd = std::numeric_limits<IT>::max();
+    IT ptr_small[16], end_small[16], head_small[16];
+    std::vector<IT> big;
+    IT *ptr = ptr_small, *end = end_small, *head = head_small;
+    if (cluster_sz > 16) {
+      big.resize(3 * cluster_sz);
+      ptr = big.data(); end = ptr + cluster_sz; head = end + cluster_sz;
+    }
+    for (IT l = 0; l < cluster_sz; ++l) {
+      if (l < lanes) { ptr[l] = A.rowptr[first + l]; end[l] = A.rowptr[first + l + 1]; }
+      else { ptr[l] = end[l] = 0; }
+      head[l] = ptr[l] < end[l] ? A.colids[ptr[l]] : kEnd;
+    }
+    IT n = 0;
+    while (true) {
+      IT m = kEnd;
+      for (IT l = 0; l < cluster_sz; ++l) m = head[l] < m ? head[l] : m;
+      if (m == kEnd) break;
+      NT *v = out_vals ? out_vals + n * cluster_sz : nullptr;
+      for (IT l = 0; l < cluster_sz; ++l) {
+        if (head[l] == m) {
+          if (v) v[l] = A.values[ptr[l]];
+          ++ptr[l];
+          head[l] = ptr[l] < end[l] ? A.colids[ptr[l]] : kEnd;
+        } else if (v) {
+          v[l] = NT(0);
+        }
+      }
+      if (out_cols) out_cols[n] = m;
+      ++n;
+    }
+    return n;
+  }
 };

 #endif
diff --git a/frontier_solution/fsol_alloc.h b/frontier_solution/fsol_alloc.h
new file mode 100644
index 0000000..08a9dd5
--- /dev/null
+++ b/frontier_solution/fsol_alloc.h
@@ -0,0 +1,179 @@
+#ifndef FSOL_ALLOC_H
+#define FSOL_ALLOC_H
+// Replacement global operator new/delete (the replaceable forms; this header is
+// included by exactly one translation unit).
+//
+// Requests of at least kLargeBlock bytes are served from 2 MiB-aligned private
+// mappings with transparent huge pages requested, so multi-hundred-megabyte
+// arrays fault in large pages and unmap cheaply. Freed large blocks are kept in
+// a small cache and reused by later requests of similar size. Smaller requests
+// go to malloc unchanged. A large block is recognised on release by its fixed
+// offset inside a 2 MiB page and by the registry of live large blocks.
+
+#include <sys/mman.h>
+#include <atomic>
+#include <cstddef>
+#include <cstdint>
+#include <cstdlib>
+#include <new>
+
+namespace fsol {
+namespace heap {
+
+constexpr size_t kLargeBlock = size_t(2) << 20;
+constexpr size_t kPage = size_t(2) << 20;
+constexpr uintptr_t kOffset = 64;         // user pointer offset inside the mapping
+constexpr int kMaxLive = 4096;
+constexpr int kMaxCached = 16;
+constexpr size_t kMaxCachedBytes = size_t(8) << 30;
+
+struct Span {
+  uintptr_t base;
+  size_t len;
+};
+
+// Constant-initialized state: usable before any dynamic initialization.
+static std::atomic_flag g_lock = ATOMIC_FLAG_INIT;
+static Span g_live[kMaxLive];
+static int g_nlive = 0;
+static Span g_cache[kMaxCached];
+static int g_ncached = 0;
+static size_t g_cached_bytes = 0;
+
+struct Guard {
+  Guard() { while (g_lock.test_and_set(std::memory_order_acquire)) { } }
+  ~Guard() { g_lock.clear(std::memory_order_release); }
+};
+
+inline size_t mapping_length(size_t bytes) { return (bytes + kOffset + kPage - 1) / kPage * kPage; }
+
+// Maps len bytes (a multiple of kPage) at a kPage-aligned address.
+inline uintptr_t map_aligned(size_t len) {
+  void *m = mmap(nullptr, len + kPage, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
+  if (m == MAP_FAILED) return 0;
+  const uintptr_t raw = reinterpret_cast<uintptr_t>(m);
+  const uintptr_t base = (raw + kPage - 1) & ~(uintptr_t)(kPage - 1);
+  if (base > raw) munmap(m, base - raw);
+  const uintptr_t tail = base + len, raw_end = raw + len + kPage;
+  if (raw_end > tail) munmap(reinterpret_cast<void *>(tail), raw_end - tail);
+  madvise(reinterpret_cast<void *>(base), len, MADV_HUGEPAGE);
+  return base;
+}
+
+// Returns a mapping of at least len bytes: a cached one no larger than twice
+// the request, or a new one. Returns 0 when the live registry is full or the
+// mapping fails.
+inline Span take(size_t len) {
+  {
+    Guard g;
+    if (g_nlive >= kMaxLive) return Span{0, 0};
+    int best = -1;
+    for (int i = 0; i < g_ncached; ++i)
+      if (g_cache[i].len >= len && g_cache[i].len / 2 <= len && (best < 0 || g_cache[i].len < g_cache[best].len)) best = i;
+    if (best >= 0) {
+      const Span s = g_cache[best];
+      g_cache[best] = g_cache[--g_ncached];
+      g_cached_bytes -= s.len;
+      g_live[g_nlive++] = s;
+      return s;
+    }
+  }
+  const uintptr_t base = map_aligned(len);
+  if (!base) return Span{0, 0};
+  Guard g;
+  if (g_nlive >= kMaxLive) {
+    munmap(reinterpret_cast<void *>(base), len);
+    return Span{0, 0};
+  }
+  g_live[g_nlive++] = Span{base, len};
+  return Span{base, len};
+}
+
+inline void *alloc(size_t bytes) {
+  if (bytes >= kLargeBlock) {
+    const Span s = take(mapping_length(bytes));
+    if (s.base) return reinterpret_cast<void *>(s.base + kOffset);
+  }
+  return std::malloc(bytes ? bytes : 1);
+}
+
+inline void dealloc(void *p) {
+  if (!p) return;
+  const uintptr_t u = reinterpret_cast<uintptr_t>(p);
+  if ((u & (kPage - 1)) == kOffset) {
+    Span s{0, 0};
+    {
+      Guard g;
+      for (int i = 0; i < g_nlive; ++i) {
+        if (g_live[i].base == u - kOffset) {
+          s = g_live[i];
+          g_live[i] = g_live[--g_nlive];
+          break;
+        }
+      }
+      if (s.base && g_ncached < kMaxCached && g_cached_bytes + s.len <= kMaxCachedBytes) {
+        g_cache[g_ncached++] = s;
+        g_cached_bytes += s.len;
+        return;
+      }
+    }
+    if (s.base) {
+      munmap(reinterpret_cast<void *>(s.base), s.len);
+      return;
+    }
+  }
+  std::free(p);
+}
+
+inline void *alloc_or_throw(size_t bytes) {
+  while (true) {
+    void *p = alloc(bytes);
+    if (p) return p;
+    std::new_handler h = std::get_new_handler();
+    if (!h) throw std::bad_alloc();
+    h();
+  }
+}
+
+inline void *alloc_aligned(size_t bytes, size_t align) {
+  if (align <= alignof(std::max_align_t) || (bytes >= kLargeBlock && align <= kOffset)) return alloc(bytes);
+  void *p = nullptr;
+  if (posix_memalign(&p, align, bytes ? bytes : 1) != 0) return nullptr;
+  return p;
+}
+
+inline void *alloc_aligned_or_throw(size_t bytes, size_t align) {
+  while (true) {
+    void *p = alloc_aligned(bytes, align);
+    if (p) return p;
+    std::new_handler h = std::get_new_handler();
+    if (!h) throw std::bad_alloc();
+    h();
+  }
+}
+
+}  // namespace heap
+}  // namespace fsol
+
+void *operator new(std::size_t n) { return fsol::heap::alloc_or_throw(n); }
+void *operator new[](std::size_t n) { return fsol::heap::alloc_or_throw(n); }
+void *operator new(std::size_t n, const std::nothrow_t &) noexcept { return fsol::heap::alloc(n); }
+void *operator new[](std::size_t n, const std::nothrow_t &) noexcept { return fsol::heap::alloc(n); }
+void *operator new(std::size_t n, std::align_val_t a) { return fsol::heap::alloc_aligned_or_throw(n, static_cast<size_t>(a)); }
+void *operator new[](std::size_t n, std::align_val_t a) { return fsol::heap::alloc_aligned_or_throw(n, static_cast<size_t>(a)); }
+void *operator new(std::size_t n, std::align_val_t a, const std::nothrow_t &) noexcept { return fsol::heap::alloc_aligned(n, static_cast<size_t>(a)); }
+void *operator new[](std::size_t n, std::align_val_t a, const std::nothrow_t &) noexcept { return fsol::heap::alloc_aligned(n, static_cast<size_t>(a)); }
+void operator delete(void *p) noexcept { fsol::heap::dealloc(p); }
+void operator delete[](void *p) noexcept { fsol::heap::dealloc(p); }
+void operator delete(void *p, const std::nothrow_t &) noexcept { fsol::heap::dealloc(p); }
+void operator delete[](void *p, const std::nothrow_t &) noexcept { fsol::heap::dealloc(p); }
+void operator delete(void *p, std::size_t) noexcept { fsol::heap::dealloc(p); }
+void operator delete[](void *p, std::size_t) noexcept { fsol::heap::dealloc(p); }
+void operator delete(void *p, std::align_val_t) noexcept { fsol::heap::dealloc(p); }
+void operator delete[](void *p, std::align_val_t) noexcept { fsol::heap::dealloc(p); }
+void operator delete(void *p, std::size_t, std::align_val_t) noexcept { fsol::heap::dealloc(p); }
+void operator delete[](void *p, std::size_t, std::align_val_t) noexcept { fsol::heap::dealloc(p); }
+void operator delete(void *p, std::align_val_t, const std::nothrow_t &) noexcept { fsol::heap::dealloc(p); }
+void operator delete[](void *p, std::align_val_t, const std::nothrow_t &) noexcept { fsol::heap::dealloc(p); }
+
+#endif
diff --git a/frontier_solution/fsol_memory.h b/frontier_solution/fsol_memory.h
new file mode 100644
index 0000000..2cacc3c
--- /dev/null
+++ b/frontier_solution/fsol_memory.h
@@ -0,0 +1,77 @@
+#ifndef FSOL_MEMORY_H
+#define FSOL_MEMORY_H
+// Large-buffer allocation for the clustered SpGEMM path.
+//
+// Products and their scratch buffers can reach gigabytes. Small-page faults on
+// such buffers do not scale with threads and unmapping them is slow, so large
+// buffers are mapped directly, 2 MiB aligned, with transparent huge pages
+// requested. New blocks are always zero-filled. Buffers are released with
+// fsol::release (never my_free).
+
+#include <sys/mman.h>
+#include <cstddef>
+#include <cstdint>
+#include <cstdlib>
+#include <cstring>
+#include <new>
+
+namespace fsol {
+
+constexpr size_t kHugePage = size_t(2) << 20;
+constexpr size_t kMapThreshold = size_t(1) << 20;
+
+struct Block {
+  void *base = nullptr;   // start of the mapping (or malloc block)
+  size_t bytes = 0;       // mapped length (0 for malloc blocks)
+  void *ptr = nullptr;    // aligned user pointer
+  size_t capacity = 0;    // usable bytes from ptr
+};
+
+// huge: request transparent huge pages. Per-thread scratch that is touched
+// sparsely uses small pages so that only touched pages are ever zeroed.
+inline Block acquire(size_t bytes, bool huge = true) {
+  Block b;
+  if (bytes == 0) bytes = 64;
+  if (bytes < kMapThreshold) {
+    void *p = nullptr;
+    if (posix_memalign(&p, 64, bytes) != 0) throw std::bad_alloc();
+    std::memset(p, 0, bytes);
+    b.base = p; b.bytes = 0; b.ptr = p; b.capacity = bytes;
+    return b;
+  }
+  size_t len = (bytes + kHugePage - 1) / kHugePage * kHugePage + kHugePage;
+  void *m = mmap(nullptr, len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
+  if (m == MAP_FAILED) {
+    // Fall back to the C heap (zero-filled, as mappings are).
+    void *p = nullptr;
+    if (posix_memalign(&p, 64, bytes) != 0) throw std::bad_alloc();
+    std::memset(p, 0, bytes);
+    b.base = p; b.bytes = 0; b.ptr = p; b.capacity = bytes;
+    return b;
+  }
+  uintptr_t start = (reinterpret_cast<uintptr_t>(m) + kHugePage - 1) & ~(uintptr_t)(kHugePage - 1);
+  if (huge) madvise(reinterpret_cast<void *>(start), len - (start - reinterpret_cast<uintptr_t>(m)), MADV_HUGEPAGE);
+  b.base = m; b.bytes = len; b.ptr = reinterpret_cast<void *>(start);
+  b.capacity = len - (start - reinterpret_cast<uintptr_t>(m));
+  return b;
+}
+
+inline void release(Block &b) {
+  if (b.base) {
+    if (b.bytes) munmap(b.base, b.bytes);
+    else free(b.base);
+  }
+  b = Block();
+}
+
+// Keeps a block when it is large enough, otherwise replaces it.
+inline void *reserve(Block &b, size_t bytes, bool huge = true) {
+  if (b.ptr && b.capacity >= bytes) return b.ptr;
+  release(b);
+  b = acquire(bytes, huge);
+  return b.ptr;
+}
+
+}  // namespace fsol
+
+#endif
diff --git a/frontier_solution/fsol_spgemm.h b/frontier_solution/fsol_spgemm.h
new file mode 100644
index 0000000..47145cd
--- /dev/null
+++ b/frontier_solution/fsol_spgemm.h
@@ -0,0 +1,761 @@
+#ifndef FSOL_SPGEMM_H
+#define FSOL_SPGEMM_H
+// Clustered SpGEMM C = A_cluster * B with the source's ordered arithmetic:
+// for each group, union columns k are visited in ascending order and B[k,:] in
+// ascending order; the first path to an output column initializes all lanes to
+// a_lane * b, later paths add (a_lane * b) + c only on lanes whose
+// |a_lane| >= double(0.000001f).
+//
+// Two phases per call: a symbolic count of every group's output columns, then
+// a numeric phase writing directly into the exact output slots. A group whose
+// output columns span a narrow range uses direct indexing into a per-thread
+// window; wider groups use open addressing. Output slots are assigned in
+// first-appearance order, so a path is the first one to its column exactly
+// when its slot equals the next unassigned slot.
+//
+// All-zero output columns may be omitted. A column is structurally nonzero
+// when its first path has b != 0 and some a_lane != 0, or a later path has
+// b != 0 and some |a_lane| >= threshold; every other column is exactly zero in
+// all lanes. When B stores zero values, the symbolic phase counts both all
+// columns and structurally nonzero ones, and the numeric phase drops the
+// structurally zero columns when that shrinks the product noticeably.
+
+#include <omp.h>
+#include <immintrin.h>
+#include <algorithm>
+#include <cstdint>
+#include <cstring>
+#include <functional>
+#include <limits>
+#include <type_traits>
+#include <vector>
+#include "fsol_memory.h"
+
+#ifdef FSOL_TIMING
+#include <cstdio>
+#define FSOL_TIMER(name) const double name = omp_get_wtime()
+#define FSOL_REPORT(...) std::fprintf(stderr, __VA_ARGS__)
+#else
+#define FSOL_TIMER(name)
+#define FSOL_REPORT(...)
+#endif
+
+// Products and sums must stay separately rounded, as in the reference.
+#pragma GCC push_options
+#pragma GCC optimize("fp-contract=off")
+
+namespace fsol {
+
+constexpr double kUpdateThreshold = static_cast<double>(0.000001f);
+constexpr int64_t kWindowMax = int64_t(1) << 20;      // widest direct-indexed span
+constexpr int64_t kWindowAlways = int64_t(1) << 15;   // spans always direct-indexed
+constexpr int64_t kScratchEntries = int64_t(1) << 13; // accumulate in scratch up to this many columns
+constexpr int64_t kSymPrefetch = 24;                  // union columns ahead (symbolic)
+constexpr int64_t kNumPrefetch = 6;                   // union columns ahead (numeric)
+constexpr uint32_t kZeroBit = 0x80000000u;            // B entry stores a zero value
+constexpr uint32_t kColMask = 0x7fffffffu;
+constexpr uint32_t kEmpty = 0xffffffffu;
+constexpr uint8_t kAnyNonzero = 1;                    // A entry flags
+constexpr uint8_t kAnyUpdate = 2;
+
+// Lane flags of one clustered A entry (8 values).
+inline uint8_t lane_flags(const double *a) {
+  uint8_t f = 0;
+  for (int l = 0; l < 8; ++l) {
+    if (a[l] != 0.0) f |= kAnyNonzero;
+    if (std::abs(a[l]) >= kUpdateThreshold) f |= kAnyUpdate;
+  }
+  return f;
+}
+
+struct ThreadScratch {
+  Block stamp;      // uint32_t[kWindowMax], symbolic window marks (epoch based)
+  Block slot;       // int32_t[kWindowMax], numeric window: output slot + 1, 0 = absent
+  Block table;      // hash entries
+  Block acc;        // 8 doubles per output column
+  Block cols;       // output columns of the current group (+1 spare)
+  Block live;       // per-slot structurally-nonzero flags
+  uint32_t epoch = 0;
+  bool ready = false;
+};
+
+struct Workspace {
+  std::vector<ThreadScratch> threads;
+  Block lo;         // per-group window base, or -1 for hashing
+  Block total;      // per-group count of all distinct output columns
+  Block bc;         // B column ids (32 bit) with kZeroBit
+  Block work;       // per-group work prefix sums
+  Block chunks;     // work-balanced chunks of groups, heaviest first
+};
+
+inline Workspace &workspace() {
+  static Workspace ws;
+  return ws;
+}
+
+inline ThreadScratch &thread_scratch(Workspace &ws, int tid) {
+  ThreadScratch &t = ws.threads[tid];
+  if (!t.ready) {
+    // Zero-filled mappings: untouched window pages are never faulted in.
+    reserve(t.stamp, sizeof(uint32_t) * kWindowMax, false);
+    reserve(t.slot, sizeof(int32_t) * kWindowMax, false);
+    reserve(t.acc, sizeof(double) * 8 * kScratchEntries, false);
+    reserve(t.cols, sizeof(int64_t) * (kScratchEntries + 1), false);
+    reserve(t.live, kScratchEntries + 64, false);
+    t.ready = true;
+  }
+  return t;
+}
+
+// Next symbolic epoch; marks from earlier groups are always smaller. Epochs
+// advance by two so that zero-aware marks can use epoch + 1.
+inline uint32_t next_epoch(ThreadScratch &ts) {
+  if (ts.epoch >= 0xfffffff0u) {
+    std::memset(ts.stamp.ptr, 0, sizeof(uint32_t) * kWindowMax);
+    ts.epoch = 0;
+  }
+  ts.epoch += 2;
+  return ts.epoch;
+}
+
+inline int ceil_log2(int64_t x) {
+  int b = 0;
+  while ((int64_t(1) << b) < x) ++b;
+  return b;
+}
+
+inline uint32_t hash_index(uint32_t key, int shift) {
+  return static_cast<uint32_t>(key * 2654435761u) >> shift;
+}
+
+inline void prefetch(const void *p) { __builtin_prefetch(p, 0, 3); }
+
+// Exclusive prefix sum of counts stored at p[1..n] into p[0..n] (p[0] = 0).
+template <typename IT>
+inline void prefix_sum_inplace(IT *p, IT n) {
+  p[0] = 0;
+  const int nt = omp_get_max_threads();
+  if (n < (IT(1) << 16) || nt == 1) {
+    for (IT i = 0; i < n; ++i) p[i + 1] += p[i];
+    return;
+  }
+  std::vector<IT> part(nt + 1, 0);
+#pragma omp parallel num_threads(nt)
+  {
+    const int t = omp_get_thread_num(), T = omp_get_num_threads();
+    const IT b = 1 + n * t / T, e = 1 + n * (t + 1) / T;
+    IT s = 0;
+    for (IT i = b; i < e; ++i) { s += p[i]; p[i] = s; }
+    part[t + 1] = s;
+#pragma omp barrier
+#pragma omp single
+    for (int i = 0; i < T; ++i) part[i + 1] += part[i];
+    const IT add = part[t];
+    if (add) for (IT i = b; i < e; ++i) p[i] += add;
+  }
+}
+
+// A contiguous range of groups and its estimated work.
+struct Chunk {
+  int64_t begin, end, work;
+};
+
+// Splits groups into about `target` contiguous chunks of similar work
+// (B entries visited plus a per-column overhead). When a few groups dominate,
+// their chunks are ordered heaviest first so dynamic scheduling ends evenly.
+inline int64_t plan_chunks(Workspace &ws, const int64_t *arpt, const int64_t *acol, const int64_t *brpt,
+                           int64_t groups, int64_t target, int nt, Chunk *&out) {
+  int64_t *pw = static_cast<int64_t *>(reserve(ws.work, sizeof(int64_t) * (groups + 1)));
+#pragma omp parallel for schedule(static) num_threads(nt)
+  for (int64_t g = 0; g < groups; ++g) {
+    int64_t w = 8 + (arpt[g + 1] - arpt[g]);
+    for (int64_t j = arpt[g]; j < arpt[g + 1]; ++j) w += brpt[acol[j] + 1] - brpt[acol[j]];
+    pw[g + 1] = w;
+  }
+  prefix_sum_inplace<int64_t>(pw, groups);
+  const int64_t total = pw[groups];
+  const int64_t want = std::max<int64_t>(1, std::min(groups, target));
+  Chunk *ch = static_cast<Chunk *>(reserve(ws.chunks, sizeof(Chunk) * (want + 1)));
+  int64_t n = 0, begin = 0;
+  for (int64_t i = 1; i <= want && begin < groups; ++i) {
+    int64_t end = i == want ? groups
+                            : std::lower_bound(pw + begin + 1, pw + groups + 1, total / want * i +
+                                               (total % want) * i / want) - pw;
+    if (end <= begin) continue;
+    end = std::min(end, groups);
+    ch[n++] = Chunk{begin, end, pw[end] - pw[begin]};
+    begin = end;
+  }
+  if (begin < groups) ch[n++] = Chunk{begin, groups, pw[groups] - pw[begin]};
+  // Chunks of similar work keep their natural order, so that concurrently
+  // processed chunks touch nearby rows of B.
+  int64_t heaviest = 0;
+  for (int64_t i = 0; i < n; ++i) heaviest = std::max(heaviest, ch[i].work);
+  if (n > 0 && heaviest > 2 * (total / n))
+    std::stable_sort(ch, ch + n, [](const Chunk &x, const Chunk &y) { return x.work > y.work; });
+  out = ch;
+  return n;
+}
+
+// Inputs shared by both phases. Column bounds of B rows come from their first
+// and last entries when B is sorted; otherwise every entry is scanned.
+struct Inputs {
+  const int64_t *arpt, *acol;
+  const double *aval;
+  const uint8_t *aflag;   // kAnyNonzero / kAnyUpdate per clustered A entry
+  const int64_t *brpt;
+  const uint32_t *bc;     // B columns, kZeroBit when the stored value is zero
+  const double *bval;
+  int64_t ncols;
+  bool b_sorted;
+};
+
+// ---------------------------------------------------------------------------
+// Symbolic phase
+// ---------------------------------------------------------------------------
+
+struct GroupCount {
+  int64_t total;    // distinct output columns
+  int64_t live;     // structurally nonzero output columns (kZero only)
+};
+
+// Counts the output columns of group g and sets its window base (-1 =
+// hashed). `jend` bounds prefetching to the current chunk.
+template <bool kZero>
+inline GroupCount symbolic_group(const Inputs &in, int64_t g, int64_t jend, ThreadScratch &ts, int64_t &lo_out) {
+  const int64_t *acol = in.acol, *brpt = in.brpt;
+  const uint32_t *bc = in.bc;
+  const uint8_t *aflag = in.aflag;
+  const int64_t j0 = in.arpt[g], j1 = in.arpt[g + 1];
+  int64_t flops = 0, lo = std::numeric_limits<int64_t>::max(), hi = -1;
+  for (int64_t j = j0; j < j1; ++j) {
+    if (j + 2 * kSymPrefetch < jend) prefetch(brpt + acol[j + 2 * kSymPrefetch]);
+    if (j + kSymPrefetch < jend) {
+      const int64_t kk = acol[j + kSymPrefetch];
+      prefetch(bc + brpt[kk]);
+      prefetch(bc + brpt[kk + 1] - 1);
+    }
+    const int64_t k = acol[j];
+    const int64_t q0 = brpt[k], q1 = brpt[k + 1];
+    if (q1 == q0) continue;
+    flops += q1 - q0;
+    if (in.b_sorted) {
+      lo = std::min<int64_t>(lo, bc[q0] & kColMask);
+      hi = std::max<int64_t>(hi, bc[q1 - 1] & kColMask);
+    } else {
+      for (int64_t q = q0; q < q1; ++q) {
+        const int64_t c = bc[q] & kColMask;
+        lo = std::min(lo, c);
+        hi = std::max(hi, c);
+      }
+    }
+  }
+  GroupCount r = {0, 0};
+  if (flops == 0) { lo_out = 0; return r; }
+  const int64_t span = hi - lo + 1;
+  if (span <= kWindowAlways || (span <= kWindowMax && span <= 32 * flops)) {
+    const uint32_t e = next_epoch(ts);
+    uint32_t *st = static_cast<uint32_t *>(ts.stamp.ptr) - lo;
+    int64_t total = 0, live = 0;
+    for (int64_t j = j0; j < j1; ++j) {
+      const int64_t k = acol[j];
+      const int64_t q1 = brpt[k + 1];
+      if (kZero) {
+        const uint32_t fa = aflag[j] & kAnyNonzero, fu = (aflag[j] & kAnyUpdate) >> 1;
+        for (int64_t q = brpt[k]; q < q1; ++q) {
+          const uint32_t w = bc[q];
+          const int64_t c = w & kColMask;
+          const uint32_t bnz = (w >> 31) ^ 1u;
+          const uint32_t old = st[c];
+          const uint32_t first = old < e;
+          const uint32_t was = old == e + 1;
+          const uint32_t contrib = bnz & (first ? fa : fu);
+          total += first;
+          live += contrib & (was ^ 1u);
+          st[c] = e + (was | contrib);
+        }
+      } else {
+        for (int64_t q = brpt[k]; q < q1; ++q) {
+          const int64_t c = bc[q] & kColMask;
+          total += st[c] != e;
+          st[c] = e;
+        }
+      }
+    }
+    lo_out = lo;
+    r.total = total;
+    r.live = kZero ? live : total;
+    return r;
+  }
+  // Open addressing on column keys; kZero keeps the nonzero flag in bit 31.
+  const int64_t bound = std::min(flops, in.ncols);
+  const int bits = std::max(4, ceil_log2(2 * bound));
+  const size_t size = size_t(1) << bits;
+  uint32_t *keys = static_cast<uint32_t *>(reserve(ts.table, sizeof(uint64_t) * size, false));
+  std::memset(keys, 0xff, sizeof(uint32_t) * size);
+  const int shift = 32 - bits;
+  const uint32_t mask = static_cast<uint32_t>(size - 1);
+  int64_t total = 0, live = 0;
+  for (int64_t j = j0; j < j1; ++j) {
+    const int64_t k = acol[j];
+    const int64_t q1 = brpt[k + 1];
+    const uint32_t fa = kZero ? (aflag[j] & kAnyNonzero) : 0u;
+    const uint32_t fu = kZero ? ((aflag[j] & kAnyUpdate) >> 1) : 0u;
+    for (int64_t q = brpt[k]; q < q1; ++q) {
+      const uint32_t w = bc[q];
+      const uint32_t c = w & kColMask;
+      uint32_t h = hash_index(c, shift);
+      uint32_t kk;
+      while ((kk = keys[h]) != kEmpty && (kk & kColMask) != c) h = (h + 1) & mask;
+      const uint32_t first = kk == kEmpty;
+      total += first;
+      if (kZero) {
+        const uint32_t bnz = (w >> 31) ^ 1u;
+        const uint32_t was = (kk >> 31) & (first ^ 1u);
+        const uint32_t contrib = bnz & (first ? fa : fu);
+        live += contrib & (was ^ 1u);
+        keys[h] = c | ((was | contrib) << 31);
+      } else {
+        keys[h] = c;
+      }
+    }
+  }
+  lo_out = -1;
+  r.total = total;
+  r.live = kZero ? live : total;
+  return r;
+}
+
+// ---------------------------------------------------------------------------
+// Numeric phase, width 8, double values
+// ---------------------------------------------------------------------------
+
+struct HashTable {
+  uint64_t *e;
+  int shift;
+  uint32_t mask;
+};
+
+inline HashTable prepare_hash(ThreadScratch &ts, int64_t cnt) {
+  const int bits = std::max(4, ceil_log2(4 * cnt));
+  const size_t size = size_t(1) << bits;
+  HashTable h;
+  h.e = static_cast<uint64_t *>(reserve(ts.table, sizeof(uint64_t) * size, false));
+  std::memset(h.e, 0xff, sizeof(uint64_t) * size);
+  h.shift = 32 - bits;
+  h.mask = static_cast<uint32_t>(size - 1);
+  return h;
+}
+
+// Output slot of column c, assigning slot n when absent.
+inline int64_t hash_slot(HashTable &h, uint32_t c, int64_t n) {
+  uint32_t i = hash_index(c, h.shift);
+  uint64_t e;
+  while (static_cast<uint32_t>(e = h.e[i]) != c && static_cast<uint32_t>(e) != kEmpty) i = (i + 1) & h.mask;
+  const int64_t s = static_cast<uint32_t>(e) == c ? static_cast<int64_t>(e >> 32) : n;
+  h.e[i] = (static_cast<uint64_t>(s) << 32) | c;
+  return s;
+}
+
+// Accumulates group rows j0..j1 into acc (8 doubles per slot, slots in
+// first-appearance order) and their columns into cols; returns the count.
+// Window mode: sl is indexed by absolute column and holds slot + 1. Hashed
+// groups mostly see first insertions, so they update branch-free; in windowed
+// groups updates dominate and a predictable branch is cheaper. With kZero,
+// live[slot] records whether the column is structurally nonzero.
+template <bool kHash, bool kZero>
+__attribute__((target("avx512f,avx512dq,avx512bw,avx512vl")))
+inline int64_t numeric_group_avx512(const Inputs &in, int64_t j0, int64_t j1, int64_t jend,
+                                    int32_t *sl, HashTable *ht, int64_t *cols, double *acc, uint8_t *live) {
+  const int64_t *acol = in.acol, *brpt = in.brpt;
+  const uint32_t *bc = in.bc;
+  const double *aval = in.aval, *bval = in.bval;
+  const __m512d thr = _mm512_set1_pd(kUpdateThreshold);
+  int64_t n = 0;
+  for (int64_t j = j0; j < j1; ++j) {
+    if (j + 2 * kNumPrefetch < jend) prefetch(brpt + acol[j + 2 * kNumPrefetch]);
+    if (j + kNumPrefetch < jend) {
+      const int64_t qq = brpt[acol[j + kNumPrefetch]];
+      prefetch(bc + qq);
+      prefetch(bval + qq);
+      prefetch(aval + (j + kNumPrefetch) * 8);
+    }
+    const int64_t k = acol[j];
+    const __m512d a = _mm512_load_pd(aval + j * 8);
+    const __mmask8 mu = _mm512_cmp_pd_mask(_mm512_abs_pd(a), thr, _CMP_GE_OQ);
+    const uint8_t fa = kZero ? (in.aflag[j] & kAnyNonzero) : 0;
+    const uint8_t fu = kZero ? ((in.aflag[j] & kAnyUpdate) >> 1) : 0;
+    const int64_t q1 = brpt[k + 1];
+    if (mu == 0) {
+      // No lane passes the threshold: only first paths have an effect.
+      for (int64_t q = brpt[k]; q < q1; ++q) {
+        const uint32_t w = bc[q];
+        const int64_t c = w & kColMask;
+        int64_t s;
+        if (kHash) {
+          s = hash_slot(*ht, static_cast<uint32_t>(c), n);
+        } else {
+          const int64_t p = sl[c];
+          if (p) continue;
+          sl[c] = static_cast<int32_t>(n + 1);
+          s = n;
+        }
+        if (s != n) continue;
+        cols[n] = c;
+        if (kZero) live[n] = static_cast<uint8_t>(((w >> 31) ^ 1u) & fa);
+        _mm512_store_pd(acc + n * 8, _mm512_mul_pd(a, _mm512_set1_pd(bval[q])));
+        ++n;
+      }
+      continue;
+    }
+    for (int64_t q = brpt[k]; q < q1; ++q) {
+      const uint32_t w = bc[q];
+      const int64_t c = w & kColMask;
+      const uint8_t bnz = kZero ? static_cast<uint8_t>((w >> 31) ^ 1u) : 0;
+      const __m512d prod = _mm512_mul_pd(a, _mm512_set1_pd(bval[q]));
+      if (kHash) {
+        const int64_t s = hash_slot(*ht, static_cast<uint32_t>(c), n);
+        const bool first = s == n;
+        cols[n] = c;
+        if (kZero) live[s] = static_cast<uint8_t>((first ? 0 : live[s]) | (bnz & (first ? fa : fu)));
+        n += first;
+        double *d = acc + s * 8;
+        const __m512d o = _mm512_load_pd(d);
+        const __m512d u = _mm512_mask_add_pd(o, mu, o, prod);
+        _mm512_store_pd(d, _mm512_mask_mov_pd(u, static_cast<__mmask8>(-static_cast<int>(first)), prod));
+      } else {
+        const int64_t p = sl[c];
+        if (p == 0) {
+          sl[c] = static_cast<int32_t>(n + 1);
+          cols[n] = c;
+          if (kZero) live[n] = bnz & fa;
+          _mm512_store_pd(acc + n * 8, prod);
+          ++n;
+        } else {
+          // A later path with b == 0 adds only zeros.
+          if (kZero && !bnz) continue;
+          double *d = acc + (p - 1) * 8;
+          if (kZero) live[p - 1] = 1;
+          const __m512d o = _mm512_load_pd(d);
+          _mm512_store_pd(d, _mm512_mask_add_pd(o, mu, o, prod));
+        }
+      }
+    }
+  }
+  return n;
+}
+
+template <bool kHash, bool kZero>
+inline int64_t numeric_group_scalar(const Inputs &in, int64_t j0, int64_t j1, int64_t,
+                                    int32_t *sl, HashTable *ht, int64_t *cols, double *acc, uint8_t *live) {
+  const int64_t *acol = in.acol, *brpt = in.brpt;
+  const uint32_t *bc = in.bc;
+  const double *aval = in.aval, *bval = in.bval;
+  int64_t n = 0;
+  for (int64_t j = j0; j < j1; ++j) {
+    const int64_t k = acol[j];
+    const double *a = aval + j * 8;
+    bool mu[8];
+    for (int l = 0; l < 8; ++l) mu[l] = std::abs(a[l]) >= kUpdateThreshold;
+    const uint8_t fa = kZero ? (in.aflag[j] & kAnyNonzero) : 0;
+    const uint8_t fu = kZero ? ((in.aflag[j] & kAnyUpdate) >> 1) : 0;
+    const int64_t q1 = brpt[k + 1];
+    for (int64_t q = brpt[k]; q < q1; ++q) {
+      const uint32_t w = bc[q];
+      const int64_t c = w & kColMask;
+      const uint8_t bnz = kZero ? static_cast<uint8_t>((w >> 31) ^ 1u) : 0;
+      const double b = bval[q];
+      int64_t s;
+      if (kHash) {
+        s = hash_slot(*ht, static_cast<uint32_t>(c), n);
+      } else {
+        const int64_t p = sl[c];
+        s = p ? p - 1 : n;
+        sl[c] = static_cast<int32_t>(s + 1);
+      }
+      double *d = acc + s * 8;
+      if (s == n) {
+        if (kZero) live[n] = bnz & fa;
+        cols[n++] = c;
+        for (int l = 0; l < 8; ++l) d[l] = a[l] * b;
+      } else {
+        if (kZero) live[s] |= bnz & fu;
+        for (int l = 0; l < 8; ++l) if (mu[l]) d[l] = a[l] * b + d[l];
+      }
+    }
+  }
+  return n;
+}
+
+__attribute__((target("avx512f,avx512dq,avx512bw,avx512vl")))
+inline void stream_copy_avx512(double *dst, const double *src, int64_t n) {
+  for (int64_t e = 0; e < n; ++e) _mm512_stream_pd(dst + e * 8, _mm512_load_pd(src + e * 8));
+}
+
+// Copies the live entries (columns and 8-lane values) to the output, in order.
+__attribute__((target("avx512f,avx512dq,avx512bw,avx512vl")))
+inline void stream_live_avx512(int64_t *dcol, double *dval, const int64_t *cols, const double *acc,
+                               const uint8_t *live, int64_t total, int64_t cnt) {
+  int64_t w = 0;
+  for (int64_t e = 0; e < total && w < cnt; ++e) {
+    if (!live[e]) continue;
+    _mm_stream_si64(reinterpret_cast<long long *>(dcol + w), cols[e]);
+    _mm512_stream_pd(dval + w * 8, _mm512_load_pd(acc + e * 8));
+    ++w;
+  }
+}
+
+inline void stream_cols(int64_t *dst, const int64_t *src, int64_t n) {
+  for (int64_t e = 0; e < n; ++e) _mm_stream_si64(reinterpret_cast<long long *>(dst + e), src[e]);
+}
+
+inline bool have_avx512() {
+  static const bool v = __builtin_cpu_supports("avx512f") && __builtin_cpu_supports("avx512dq") &&
+                        __builtin_cpu_supports("avx512bw") && __builtin_cpu_supports("avx512vl");
+  return v;
+}
+
+// Computes group g (total distinct columns) and writes its `cnt` output
+// columns at `off`; with kZero only the structurally nonzero ones.
+template <bool kZero>
+inline void numeric_group(const Inputs &in, int64_t g, int64_t jend, int64_t lo, int64_t total,
+                          int64_t off, int64_t cnt, int64_t *ccol, double *cval, bool simd, ThreadScratch &ts) {
+  const int64_t j0 = in.arpt[g], j1 = in.arpt[g + 1];
+  const bool direct = !kZero && total > kScratchEntries;
+  double *acc = direct ? cval + off * 8
+                       : static_cast<double *>(reserve(ts.acc, sizeof(double) * 8 * total, false));
+  int64_t *cols = static_cast<int64_t *>(reserve(ts.cols, sizeof(int64_t) * (total + 1), false));
+  uint8_t *live = kZero ? static_cast<uint8_t *>(reserve(ts.live, total + 64, false)) : nullptr;
+  if (lo < 0) {
+    HashTable ht = prepare_hash(ts, total);
+    if (simd) numeric_group_avx512<true, kZero>(in, j0, j1, jend, nullptr, &ht, cols, acc, live);
+    else numeric_group_scalar<true, kZero>(in, j0, j1, jend, nullptr, &ht, cols, acc, live);
+  } else {
+    int32_t *sl = static_cast<int32_t *>(ts.slot.ptr) - lo;
+    if (simd) numeric_group_avx512<false, kZero>(in, j0, j1, jend, sl, nullptr, cols, acc, live);
+    else numeric_group_scalar<false, kZero>(in, j0, j1, jend, sl, nullptr, cols, acc, live);
+    for (int64_t e = 0; e < total; ++e) sl[cols[e]] = 0;
+  }
+  if (kZero) {
+    if (simd) {
+      stream_live_avx512(ccol + off, cval + off * 8, cols, acc, live, total, cnt);
+      return;
+    }
+    int64_t w = 0;
+    for (int64_t e = 0; e < total && w < cnt; ++e) {
+      if (!live[e]) continue;
+      ccol[off + w] = cols[e];
+      std::memcpy(cval + (off + w) * 8, acc + e * 8, sizeof(double) * 8);
+      ++w;
+    }
+    return;
+  }
+  stream_cols(ccol + off, cols, cnt);
+  if (!direct) {
+    if (simd) stream_copy_avx512(cval + off * 8, acc, cnt);
+    else std::memcpy(cval + off * 8, acc, sizeof(double) * 8 * cnt);
+  }
+}
