+// ---------------------------------------------------------------------------
+// Driver
+// ---------------------------------------------------------------------------
+
+template <bool sortOutput, typename CA, typename CB, typename CC>
+void spgemm_w8(const CA &a, const CB &b, CC &c) {
+  typedef int64_t IT;
+  Workspace &ws = workspace();
+  const int nt = omp_get_max_threads();
+  if ((int)ws.threads.size() < nt) ws.threads.resize(nt);
+  FSOL_TIMER(T0);
+
+  const IT groups = a.rows;
+  c.csr_rows = a.csr_rows;
+  c.rows = groups;
+  c.cols = b.cols;
+  c.cluster_sz = a.cluster_sz;
+  IT *crpt = static_cast<IT *>(reserve(c.mem_rowptr, sizeof(IT) * (groups + 1)));
+  IT *glo = static_cast<IT *>(reserve(ws.lo, sizeof(IT) * (groups + 1)));
+  IT *gtot = static_cast<IT *>(reserve(ws.total, sizeof(IT) * (groups + 1)));
+  c.rowptr = crpt;
+
+  // 32-bit B columns tagged with zero values.
+  const IT bnnz = b.rowptr[b.rows];
+  uint32_t *bc = static_cast<uint32_t *>(reserve(ws.bc, sizeof(uint32_t) * (bnnz + 1)));
+  IT bzeros = 0;
+  {
+    const IT *bcol = b.colids;
+    const double *bval = b.values;
+#pragma omp parallel for schedule(static) reduction(+ : bzeros) num_threads(nt)
+    for (IT q = 0; q < bnnz; ++q) {
+      const bool z = bval[q] == 0.0;
+      bc[q] = static_cast<uint32_t>(bcol[q]) | (z ? kZeroBit : 0u);
+      bzeros += z;
+    }
+  }
+  // Structurally zero columns become common only when most stored values are
+  // zero (e.g. stencils whose -1 entries the reader shifts to 0).
+  const bool zero_aware = a.flags != nullptr && bnnz > 0 && bzeros * 5 >= bnnz * 2;
+
+  Inputs in;
+  in.arpt = a.rowptr; in.acol = a.colids; in.aval = a.values; in.aflag = a.flags;
+  in.brpt = b.rowptr; in.bc = bc; in.bval = b.values;
+  in.ncols = b.cols;
+  in.b_sorted = b.is_sorted;
+
+  // Work-balanced chunks of groups, heaviest first, scheduled dynamically.
+  Chunk *chunks = nullptr;
+  const IT nchunks = plan_chunks(ws, in.arpt, in.acol, in.brpt, groups, IT(nt) * 16, nt, chunks);
+  FSOL_TIMER(T1);
+  IT live_sum = 0, total_sum = 0;
+#pragma omp parallel num_threads(nt) reduction(+ : live_sum, total_sum)
+  {
+    ThreadScratch &ts = thread_scratch(ws, omp_get_thread_num());
+#pragma omp for schedule(dynamic, 1)
+    for (IT ch = 0; ch < nchunks; ++ch) {
+      const IT g0 = chunks[ch].begin, g1 = chunks[ch].end;
+      const IT jend = in.arpt[g1];
+      for (IT g = g0; g < g1; ++g) {
+        IT lo;
+        const GroupCount r = zero_aware ? symbolic_group<true>(in, g, jend, ts, lo)
+                                        : symbolic_group<false>(in, g, jend, ts, lo);
+        crpt[g + 1] = r.live;
+        gtot[g] = r.total;
+        glo[g] = lo;
+        live_sum += r.live;
+        total_sum += r.total;
+      }
+    }
+  }
+  // Dropping columns costs extra bookkeeping per path; do it only when it
+  // removes at least 30% of the product.
+  const bool compact = zero_aware && live_sum * 10 < total_sum * 7;
+  if (zero_aware && !compact) {
+#pragma omp parallel for schedule(static) num_threads(nt)
+    for (IT g = 0; g < groups; ++g) crpt[g + 1] = gtot[g];
+  }
+  FSOL_TIMER(T2);
+  prefix_sum_inplace<IT>(crpt, groups);
+  const IT nnzc = crpt[groups];
+  c.nnzc = nnzc;
+  IT *ccol = static_cast<IT *>(reserve(c.mem_colids, sizeof(IT) * (nnzc + 1)));
+  double *cval = static_cast<double *>(reserve(c.mem_values, sizeof(double) * 8 * (nnzc + 1)));
+  c.colids = ccol;
+  c.values = cval;
+
+  const bool simd = have_avx512();
+  FSOL_TIMER(T3);
+#pragma omp parallel num_threads(nt)
+  {
+    ThreadScratch &ts = thread_scratch(ws, omp_get_thread_num());
+#pragma omp for schedule(dynamic, 1)
+    for (IT ch = 0; ch < nchunks; ++ch) {
+      const IT g0 = chunks[ch].begin, g1 = chunks[ch].end;
+      const IT jend = in.arpt[g1];
+      for (IT g = g0; g < g1; ++g) {
+        const IT off = crpt[g], cnt = crpt[g + 1] - off;
+        if (gtot[g] == 0) continue;
+        if (compact) numeric_group<true>(in, g, jend, glo[g], gtot[g], off, cnt, ccol, cval, simd, ts);
+        else numeric_group<false>(in, g, jend, glo[g], gtot[g], off, cnt, ccol, cval, simd, ts);
+        if (sortOutput) {
+          // Order the group's columns ascending (not used by the program).
+          std::vector<std::pair<IT, IT>> order(cnt);
+          for (IT e = 0; e < cnt; ++e) order[e] = std::make_pair(ccol[off + e], e);
+          std::sort(order.begin(), order.end());
+          std::vector<double> tmp(cval + off * 8, cval + (off + cnt) * 8);
+          for (IT e = 0; e < cnt; ++e) {
+            ccol[off + e] = order[e].first;
+            std::memcpy(cval + (off + e) * 8, tmp.data() + order[e].second * 8, sizeof(double) * 8);
+          }
+        }
+      }
+    }
+    _mm_sfence();
+  }
+  FSOL_TIMER(T4);
+  FSOL_REPORT("[k] bconv+plan %.1f sym %.1f scan+alloc %.1f num %.1f ms (zeros %ld, live %ld / %ld, compact %d, chunks %ld)\n",
+              (T1 - T0) * 1e3, (T2 - T1) * 1e3, (T3 - T2) * 1e3, (T4 - T3) * 1e3,
+              (long)bzeros, (long)live_sum, (long)total_sum, (int)compact, (long)nchunks);
+}
+
+// Generic fallback: any width, index and value types, operations.
+template <bool sortOutput, typename IT, typename NT, typename MultiplyOperation, typename AddOperation,
+          typename CA, typename CB, typename CC>
+void spgemm_generic(const CA &a, const CB &b, CC &c, MultiplyOperation multop, AddOperation addop) {
+  const IT W = a.cluster_sz;
+  const IT groups = a.rows;
+  c.csr_rows = a.csr_rows;
+  c.rows = groups;
+  c.cols = b.cols;
+  c.cluster_sz = W;
+  IT *crpt = static_cast<IT *>(reserve(c.mem_rowptr, sizeof(IT) * (groups + 1)));
+  c.rowptr = crpt;
+  const NT thr = static_cast<NT>(kUpdateThreshold);
+#pragma omp parallel
+  {
+    std::vector<IT> mark(b.cols, -1);
+    std::vector<IT> list;
+#pragma omp for schedule(dynamic, 16)
+    for (IT g = 0; g < groups; ++g) {
+      list.clear();
+      for (IT j = a.rowptr[g]; j < a.rowptr[g + 1]; ++j) {
+        const IT k = a.colids[j];
+        for (IT q = b.rowptr[k]; q < b.rowptr[k + 1]; ++q) {
+          const IT col = b.colids[q];
+          if (mark[col] < 0) { mark[col] = 1; list.push_back(col); }
+        }
+      }
+      for (IT col : list) mark[col] = -1;
+      crpt[g + 1] = static_cast<IT>(list.size());
+    }
+  }
+  prefix_sum_inplace<IT>(crpt, groups);
+  c.nnzc = crpt[groups];
+  IT *ccol = static_cast<IT *>(reserve(c.mem_colids, sizeof(IT) * (c.nnzc + 1)));
+  NT *cval = static_cast<NT *>(reserve(c.mem_values, sizeof(NT) * (c.nnzc * W + 1)));
+  c.colids = ccol;
+  c.values = cval;
+#pragma omp parallel
+  {
+    std::vector<IT> mark(b.cols, -1);
+#pragma omp for schedule(dynamic, 16)
+    for (IT g = 0; g < groups; ++g) {
+      const IT off = crpt[g];
+      IT n = 0;
+      for (IT j = a.rowptr[g]; j < a.rowptr[g + 1]; ++j) {
+        const IT k = a.colids[j];
+        const NT *av = a.values + j * W;
+        for (IT q = b.rowptr[k]; q < b.rowptr[k + 1]; ++q) {
+          const IT col = b.colids[q];
+          if (mark[col] < 0) {
+            mark[col] = n;
+            ccol[off + n] = col;
+            for (IT l = 0; l < W; ++l) cval[(off + n) * W + l] = multop(av[l], b.values[q]);
+            ++n;
+          } else {
+            NT *d = cval + (off + mark[col]) * W;
+            for (IT l = 0; l < W; ++l)
+              if (std::abs(av[l]) >= thr) d[l] = addop(multop(av[l], b.values[q]), d[l]);
+          }
+        }
+      }
+      for (IT e = 0; e < n; ++e) mark[ccol[off + e]] = -1;
+      if (sortOutput) {
+        std::vector<std::pair<IT, IT>> order(n);
+        for (IT e = 0; e < n; ++e) order[e] = std::make_pair(ccol[off + e], e);
+        std::sort(order.begin(), order.end());
+        std::vector<NT> tmp(cval + off * W, cval + (off + n) * W);
+        for (IT e = 0; e < n; ++e) {
+          ccol[off + e] = order[e].first;
+          for (IT l = 0; l < W; ++l) cval[(off + e) * W + l] = tmp[order[e].second * W + l];
+        }
+      }
+    }
+  }
+}
